/**
 * Keys of the automatic-acknowledgment templates that may go to a customer at any autonomy stage
 * without a person approving them (PRD section 6.4: "auto-ack allowed"; ADR-010 section 5).
 *
 * A template belongs here only if its text is fixed and contains nothing but facts the customer
 * already has or may have: the ticket key, the link to the portal tracking page, and the SLA
 * target for a first response. Nothing generated by a model, nothing about the cause, the
 * account, other customers or an incident. Adding a key is a security-relevant change: it needs a
 * review by someone other than its author (N7), and the template's text lives in the code or seed
 * that sends it, not here.
 *
 * `[ASSUMED]` names; T-102/T-103 define the actual auto-ack templates and must use these keys or
 * add theirs here in the same change.
 */
class FrozenSet<T> extends Set<T> {
  constructor(values: readonly T[]) {
    super();
    // `super.add` on purpose: this class refuses `add` once built.
    for (const value of values) super.add(value);
    Object.freeze(this);
  }
  override add(): never {
    throw new TypeError('This set is read-only');
  }
  override delete(): never {
    throw new TypeError('This set is read-only');
  }
  override clear(): never {
    throw new TypeError('This set is read-only');
  }
}

/** Read-only at run time as well as in the type: `add`, `delete` and `clear` throw (review A-7). */
export const SAFE_AUTO_ACK_TEMPLATES: ReadonlySet<string> = new FrozenSet([
  'auto_ack.received',
  'auto_ack.received_with_sla',
]);
